# ---- the same machinery as horse_race.R, kept identical on purpose --------
rss_lin <- function(y,t){n<-length(y);if(n<2)return(0);dt<-t-mean(t);dy<-y-mean(y)
  S<-sum(dt*dt); if(S<=0) return(sum(dy*dy)); sum(dy*dy)-sum(dt*dy)^2/S}
int  <- function(n){lo<-max(3,floor(0.15*n)); lo:(n-lo)}
bic  <- function(rss,n,k) n*log(rss/n)+k*log(n)

race_one <- function(y, t, label, kind = "continuous") {
  ok <- is.finite(y) & is.finite(t); y <- y[ok]; t <- t[ok]
  o <- order(t); y <- y[o]; t <- t[o]
  n <- length(y)
  if (n < 20) return(data.frame(series=label, n=n, kind=kind, shape="TOO SHORT",
                                detail="", dBIC_next=NA, flat_dBIC=NA, linear_dBIC=NA))
  r_flat <- sum((y-mean(y))^2)
  r_lin  <- sum(resid(lm(y~t))^2)
  r_quad <- sum(resid(lm(y~t+I(t^2)))^2)
  ks <- int(n)
  rr <- sapply(ks, function(k) rss_lin(y[1:k],t[1:k]) + rss_lin(y[(k+1):n],t[(k+1):n]))
  r_brk <- min(rr); k_brk <- ks[which.min(rr)]
  best <- NULL
  for (C in t[int(n)]) { m <- lm(y~t+I(pmax(t-C,0))); r <- sum(resid(m)^2)
    if (is.null(best)||r<best$r) best <- list(r=r, C=C, m=m) }
  g <- gam(y~s(t,k=min(10,max(4,floor(n/4)))), method="REML")
  r_spl <- sum(resid(g)^2); k_spl <- sum(g$edf)+1

  tab <- data.frame(
    model = c("flat","linear","quadratic","break","bend","spline"),
    bic   = c(bic(r_flat,n,2), bic(r_lin,n,3), bic(r_quad,n,4),
              bic(r_brk,n,6),  bic(best$r,n,5), bic(r_spl,n,k_spl)))
  tab <- tab[order(tab$bic),]
  tab$d <- tab$bic - tab$bic[1]

  co <- coef(best$m)
  detail <- switch(tab$model[1],
    break_  = "", `break` = sprintf("break %d", t[k_brk]),
    bend    = sprintf("knot %d (slope %+.3f -> %+.3f)", best$C, co[2], co[2]+co[3]),
    spline  = sprintf("edf %.2f", sum(g$edf)),
    linear  = sprintf("slope %+.4f/yr", coef(lm(y~t))[2]), "")

  data.frame(series = label, n = n, kind = kind,
             shape = tab$model[1], detail = detail,
             dBIC_next  = round(tab$d[2],2),
             flat_dBIC  = round(tab$d[tab$model=="flat"],2),
             linear_dBIC= round(tab$d[tab$model=="linear"],2),
             break_dBIC = round(tab$d[tab$model=="break"],2),
             break_yr   = t[k_brk], bend_knot = best$C)
}

# ---- read one series safely ------------------------------------------------
grab <- function(path, ycol, tcol="year", from=NA, to=NA) {
  if (!file.exists(path)) { message("MISSING: ", path); return(NULL) }
  d <- read.csv(path, stringsAsFactors=FALSE)
  if (!(ycol %in% names(d)) || !(tcol %in% names(d))) {
    message("COLUMN MISSING in ", path, ": ", ycol); return(NULL) }
  d <- d[, c(tcol, ycol)]; names(d) <- c("t","y")
  d <- d[is.finite(d$t) & is.finite(d$y),]
  if (!is.na(from)) d <- d[d$t >= from,]
  if (!is.na(to))   d <- d[d$t <= to,]
  d
}

