# the composite, from its own run, for comparison
comp <- read.csv("nonlinear_modelling/horse_race_composite.csv", stringsAsFactors=FALSE)
comp <- comp[order(comp$bic),]
# ⛔ 18 Aug: this row reads horse_race_composite.csv, which is a CACHED artefact. It printed a
#   stale knot (2013) for a day after the index changed. horse_race.R must be re-run FIRST;
#   the n below is now taken from the canonical file rather than hardcoded.
# ⛔ EVERY NUMBER IN THIS ROW USED TO BE A HARDCODED LITERAL typed on 16 Aug. The script read
#   horse_race_composite.csv and then ignored it, so the row kept reporting knot 2013 and
#   flat_dBIC 27.42 through three changes of specification. Now COMPUTED from that file.
.cd  <- read.csv(file.path(WS,"composite_canonical","canonical_pc1_1979_2025.csv"))
.gv  <- function(m, col) comp[[col]][comp$model == m][1]
.best <- min(comp$bic)
.seg  <- comp[comp$model == "segmented", ][1, ]
.brk  <- comp[comp$model == "break_lt",  ][1, ]
.knot <- as.integer(sub(".*?(\\d{4}).*", "\\1", .seg$detail))
.bry  <- as.integer(sub(".*?(\\d{4}).*", "\\1", .brk$detail))
# slopes either side of the knot, from the live index
.m    <- lm(PC1_index ~ year + I(pmax(year - .knot, 0)), data = .cd)
.co   <- coef(.m)
# ⚠ "bend (adopted)" is an OVERRIDE, not the criterion winner. On raw BIC/AIC/LOO the spline wins;
#   the bend is adopted on the AR(1) argument (residual rho ~ 0.57), because the criteria are
#   inflated by persistence. Label it as adopted so the table never implies the race chose it.
out <- rbind(out, data.frame(series="Fig 2.16 Turbulence index (composite)", n=nrow(.cd),
  kind="continuous",
  shape=sprintf("bend (adopted; BIC winner = %s)", comp$model[which.min(comp$bic)]),
  detail=sprintf("knot %d (slope %+.3f -> %+.3f)", .knot, .co[2], .co[2] + .co[3]),
  dBIC_next=round(sort(comp$bic)[2] - .best, 2),
  flat_dBIC=round(.gv("flat","bic") - .best, 2),
  linear_dBIC=round(.gv("linear","bic") - .best, 2),
  break_dBIC=round(.brk$bic - .best, 2),
  break_yr=.bry, bend_knot=.knot))

cat("\n================ CHAPTER 2 — ONE SELECTION RULE, ALL SERIES ================\n")
print(out[, c("series","n","kind","shape","detail","dBIC_next")], row.names=FALSE)
cat("\n--- how decisively are FLAT and LINEAR rejected? (dBIC vs the best model) ---\n")
print(out[, c("series","flat_dBIC","linear_dBIC","break_dBIC")], row.names=FALSE)

write.csv(out, "nonlinear_modelling/chapter_wide_shapes.csv", row.names=FALSE)
