pretty <- c(flat="flat", linear="linear trend", quadratic="curved",
            `break`="step", bend="bend", spline="curved (spline)",
            `bend (adopted)`="bend")
# ⚠ "->" must not reach LaTeX raw: in OT1 text mode ">" sets as an inverted question mark.
esc <- function(s) {
  s <- gsub("&", "\\\\&", s)
  # fixed=TRUE means the replacement is literal, so a single escape is correct here
  s <- gsub("->", "$\\to$", s, fixed = TRUE)
  s <- gsub("-0.000", "0.000", s, fixed = TRUE)   # a negative zero slope reads as an error
  s
}
rows <- apply(out, 1, function(r) {
  sprintf("%s & %s & %s & %s & %s \\\\",
          esc(r[["series"]]),
          r[["n"]],
          # ⛔ 18 Aug: the composite row's shape label became "bend (adopted; BIC winner = spline)" when
          #    the row was made honest about the criterion winner, and this lookup has no entry for
          #    that string, so the whole table build died. Fall back to the label itself.
          sprintf("\\textbf{%s}", ifelse(r[["shape"]] %in% names(pretty), pretty[[ r[["shape"]] ]], r[["shape"]])),
          ifelse(nzchar(trimws(r[["detail"]])), esc(trimws(r[["detail"]])), "---"),
          sprintf("%s / %s", r[["flat_dBIC"]], r[["linear_dBIC"]]))
})
